/**
 * Wiki overview: the GitHub wiki pages that show the work plan (epics,
 * sub-issues and "blocked by" dependencies) and the architecture diagrams,
 * regenerated by .github/workflows/wiki-overview.yml. Nobody edits them by
 * hand; every page says so in its first line.
 *
 * Usage (from the repo root):
 *   node tools/wiki-overview.ts --print-query
 *   node tools/wiki-overview.ts --issues <issues.json> --graph <graph.json> \
 *     --out <wiki-dir> --commit <sha>
 *
 * `--print-query` prints {@link ISSUES_QUERY}, the GraphQL query the
 * workflow runs with `gh api graphql --paginate --slurp` (variables `owner`
 * and `name`); its output is the issues file. The graph is the JSON printed by
 * tools/architecture-graph.ts. The second form writes {@link PAGE_NAMES} into
 * the wiki checkout, but only when a page changed in more than its
 * generated-time line, so the workflow commits only real changes.
 *
 * The parse and render functions are pure; reading and writing files and the
 * clock sit in the "process boundary" section at the end.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  mermaidIds,
  mermaidLabel,
  renderMermaid,
  type ArchitectureGraph,
} from './architecture-graph.ts';

/**
 * Every issue of the repository with what the work plan needs. Nested
 * connections cannot be paginated by `gh --paginate`, so the blocker list
 * asks for the maximum and {@link parseIssues} fails when it was cut short.
 */
export const ISSUES_QUERY = `query($owner: String!, $name: String!, $endCursor: String) {
  repository(owner: $owner, name: $name) {
    nameWithOwner
    issues(first: 50, after: $endCursor, orderBy: { field: CREATED_AT, direction: ASC }) {
      pageInfo { hasNextPage endCursor }
      nodes {
        number
        title
        url
        state
        issueType { name }
        labels(first: 50) { nodes { name } }
        parent { number repository { nameWithOwner } }
        subIssues { totalCount }
        blockedBy(first: 100) {
          totalCount
          nodes { number title url state repository { nameWithOwner } }
        }
      }
    }
  }
}
`;

const WORKFLOW_FILE = '.github/workflows/wiki-overview.yml';
const WORKFLOW_NAME = 'Wiki overview';
const GENERATOR = 'tools/wiki-overview.ts';
/** The one line that may change on every run without a commit. */
const GENERATED_AT_PREFIX = '生成時間：';

/**
 * Wiki page names. GitHub maps `<name>.md` in the wiki repository to the page
 * `<name>` (a `-` would show as a space), and `[[<name>]]` links resolve
 * from every page, including Home served at `/wiki` where a relative
 * Markdown link would miss the `wiki/` segment.
 */
export const PAGE_NAMES = {
  home: 'Home',
  workPlan: '工作計畫',
  architecture: '架構總覽',
} as const;

interface IssueRef {
  /** `#12` in this repository, `owner/repo#12` elsewhere. */
  key: string;
  number: number;
  title: string;
  url: string;
  open: boolean;
}

interface Issue extends IssueRef {
  /** Labelled `epic`, typed Epic, or has sub-issues. */
  epic: boolean;
  /** Key of the parent issue. */
  parent?: string;
  blockers: IssueRef[];
}

interface IssueSet {
  repository: string;
  /** Sorted by number. */
  issues: Issue[];
}

// ---- Issues -----------------------------------------------------------------

function record(value: unknown, what: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new Error(`${what} is not an object.`);
  }
  return value as Record<string, unknown>;
}

function list(value: unknown, what: string): unknown[] {
  if (!Array.isArray(value)) throw new Error(`${what} is not a list.`);
  return value;
}

function text(value: unknown, what: string): string {
  if (typeof value !== 'string') throw new Error(`${what} is not a string.`);
  return value;
}

function integer(value: unknown, what: string): number {
  if (!Number.isInteger(value)) throw new Error(`${what} is not an integer.`);
  return value as number;
}

function connectionNodes(value: unknown, what: string): unknown[] {
  return list(record(value, what).nodes, `${what}.nodes`);
}

function issueKey(repository: string, number: number, home: string): string {
  return repository === home ? `#${number}` : `${repository}#${number}`;
}

function parseRef(value: unknown, home: string, what: string): IssueRef {
  const node = record(value, what);
  const number = integer(node.number, `${what}.number`);
  const repository = text(
    record(node.repository, `${what}.repository`).nameWithOwner,
    `${what}.repository.nameWithOwner`,
  );
  return {
    key: issueKey(repository, number, home),
    number,
    title: text(node.title, `${what}.title`),
    url: text(node.url, `${what}.url`),
    open: text(node.state, `${what}.state`) === 'OPEN',
  };
}

/** This repository's issues by number, then other repositories' by name and number. */
function compareRefs(a: IssueRef, b: IssueRef): number {
  const repoA = a.key.slice(0, a.key.lastIndexOf('#'));
  const repoB = b.key.slice(0, b.key.lastIndexOf('#'));
  if (repoA !== repoB) return repoA < repoB ? -1 : 1;
  return a.number - b.number;
}

function parseIssue(value: unknown, home: string, what: string): Issue {
  const node = record(value, what);
  const number = integer(node.number, `${what}.number`);
  const blockedBy = record(node.blockedBy, `${what}.blockedBy`);
  const blockerNodes = list(blockedBy.nodes, `${what}.blockedBy.nodes`);
  if (
    integer(blockedBy.totalCount, `${what}.blockedBy.totalCount`) !==
    blockerNodes.length
  ) {
    throw new Error(
      `Issue #${number} has more blockers than the query returns; raise blockedBy(first:) in ISSUES_QUERY.`,
    );
  }
  const labels = connectionNodes(node.labels, `${what}.labels`).map((label) =>
    text(record(label, `${what}.labels[]`).name, `${what}.labels[].name`),
  );
  const issueType =
    node.issueType === null || node.issueType === undefined
      ? undefined
      : text(
          record(node.issueType, `${what}.issueType`).name,
          `${what}.issueType.name`,
        );
  const subIssueCount = integer(
    record(node.subIssues, `${what}.subIssues`).totalCount,
    `${what}.subIssues.totalCount`,
  );
  const parent =
    node.parent === null || node.parent === undefined
      ? undefined
      : record(node.parent, `${what}.parent`);
  return {
    key: `#${number}`,
    number,
    title: text(node.title, `${what}.title`),
    url: text(node.url, `${what}.url`),
    open: text(node.state, `${what}.state`) === 'OPEN',
    epic:
      labels.some((label) => label.toLowerCase() === 'epic') ||
      issueType?.toLowerCase() === 'epic' ||
      subIssueCount > 0,
    parent: parent
      ? issueKey(
          text(
            record(parent.repository, `${what}.parent.repository`)
              .nameWithOwner,
            `${what}.parent.repository.nameWithOwner`,
          ),
          integer(parent.number, `${what}.parent.number`),
          home,
        )
      : undefined,
    blockers: blockerNodes
      .map((blocker, index) =>
        parseRef(blocker, home, `${what}.blockedBy.nodes[${index}]`),
      )
      .sort(compareRefs),
  };
}

/**
 * The output of `gh api graphql --paginate --slurp` with {@link ISSUES_QUERY}
 * (a list of pages), or a single page.
 */
export function parseIssues(value: unknown): IssueSet {
  const pages = Array.isArray(value) ? value : [value];
  let repository: string | undefined;
  const issues = new Map<number, Issue>();
  pages.forEach((pageValue, pageIndex) => {
    const page = record(pageValue, `page ${pageIndex}`);
    if (page.errors !== undefined) {
      throw new Error(
        `The issues query failed: ${JSON.stringify(page.errors)}`,
      );
    }
    const repo = record(
      record(page.data, `page ${pageIndex}.data`).repository,
      `page ${pageIndex}.data.repository`,
    );
    const name = text(repo.nameWithOwner, 'repository.nameWithOwner');
    if (repository !== undefined && repository !== name) {
      throw new Error(`The pages mix repositories ${repository} and ${name}.`);
    }
    repository = name;
    connectionNodes(repo.issues, 'repository.issues').forEach((node, index) => {
      const issue = parseIssue(
        node,
        name,
        `page ${pageIndex}.issues[${index}]`,
      );
      issues.set(issue.number, issue);
    });
  });
  if (repository === undefined)
    throw new Error('The issues file has no pages.');
  return {
    repository,
    issues: [...issues.values()].sort((a, b) => a.number - b.number),
  };
}

/** Open work that is not an epic and whose blockers are all closed, by number. */
export function readyToStart(set: IssueSet): Issue[] {
  return set.issues.filter(
    (issue) =>
      issue.open &&
      !issue.epic &&
      issue.blockers.every((blocker) => !blocker.open),
  );
}

// ---- Rendering ----------------------------------------------------------------

/** Text for a Markdown paragraph or table cell, shown literally. */
function markdownText(value: string): string {
  return value
    .replace(/\s+/gu, ' ')
    .trim()
    .replace(/[\\`*_[\]|~]/gu, '\\$&')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;');
}

function issueLink(issue: IssueRef): string {
  return `[${markdownText(issue.key)}](${issue.url})`;
}

function header(source: string): string[] {
  return [
    '> 自動生成，請勿手動編輯。',
    `> 產生器：\`${GENERATOR}\`，由 GitHub Actions 工作流程「${WORKFLOW_NAME}」（\`${WORKFLOW_FILE}\`）定期重新產生；資料來源：${source}。手動修改會在下次執行時被覆蓋。`,
    '',
    `<!-- 自動生成，請勿手動編輯。Generated by ${GENERATOR} (${WORKFLOW_FILE}); manual edits are overwritten. -->`,
    '',
  ];
}

function clickTarget(url: string): string {
  return url.replaceAll('"', '%22');
}

/**
 * A `flowchart LR` of an epic's open sub-issues; `a --> b` means `a` blocks
 * `b`. Open blockers from outside the epic are drawn dashed; closed issues
 * are left out. Ready sub-issues (no open blocker) are highlighted, and every
 * node links to its issue.
 */
function epicDiagram(subIssues: Issue[]): string {
  const members = new Map(subIssues.map((issue) => [issue.key, issue]));
  const external = new Map<string, IssueRef>();
  const edges: [string, string][] = [];
  for (const issue of subIssues) {
    for (const blocker of issue.blockers) {
      if (!blocker.open) continue;
      if (!members.has(blocker.key)) external.set(blocker.key, blocker);
      edges.push([blocker.key, issue.key]);
    }
  }
  const nodes: IssueRef[] = [...subIssues, ...external.values()].sort(
    compareRefs,
  );
  const ids = mermaidIds(nodes.map((node) => node.key));
  const id = (key: string): string => ids.get(key) as string;
  const order = new Map(nodes.map((node, index) => [node.key, index]));
  edges.sort(
    ([fromA, toA], [fromB, toB]) =>
      (order.get(fromA) as number) - (order.get(fromB) as number) ||
      (order.get(toA) as number) - (order.get(toB) as number),
  );
  const lines = ['flowchart LR'];
  for (const node of nodes) {
    lines.push(
      `  ${id(node.key)}["${mermaidLabel(`${node.key} ${node.title}`)}"]`,
    );
  }
  for (const [from, to] of edges) lines.push(`  ${id(from)} --> ${id(to)}`);
  for (const node of nodes) {
    lines.push(`  click ${id(node.key)} "${clickTarget(node.url)}"`);
  }
  const ready = subIssues.filter(
    (issue) => !issue.epic && issue.blockers.every((blocker) => !blocker.open),
  );
  if (ready.length > 0) {
    lines.push('  classDef ready stroke:#1a7f37,stroke-width:3px');
    lines.push(
      `  class ${ready.map((issue) => id(issue.key)).join(',')} ready`,
    );
  }
  if (external.size > 0) {
    lines.push('  classDef external stroke-dasharray:5 5');
    lines.push(
      `  class ${[...external.keys()]
        .map((key) => id(key))
        .sort()
        .join(',')} external`,
    );
  }
  return lines.join('\n');
}

function epicSection(epic: Issue, children: Issue[]): string[] {
  const open = children.filter((issue) => issue.open);
  const closed = children.length - open.length;
  const lines = [
    `### ${issueLink(epic)} ${markdownText(epic.title)}${epic.open ? '' : '（已關閉）'}`,
    '',
    `未完成 ${open.length} 個子 issue；已完成 ${closed} 個（未畫出）。`,
    '',
  ];
  if (open.length === 0) {
    lines.push('所有子 issue 都已完成。', '');
    return lines;
  }
  lines.push('```mermaid', epicDiagram(open), '```', '');
  return lines;
}

function openBlockers(issue: Issue): string {
  const open = issue.blockers.filter((blocker) => blocker.open);
  return open.length === 0
    ? '可以開始'
    : `被 ${open.map(issueLink).join('、')} 擋住`;
}

/** The work-plan page (without a trailing time line; it has none). */
export function renderWorkPlan(set: IssueSet): string {
  const byKey = new Map(set.issues.map((issue) => [issue.key, issue]));
  const epicOf = (issue: Issue): Issue | undefined => {
    const parent = issue.parent ? byKey.get(issue.parent) : undefined;
    return parent?.epic ? parent : undefined;
  };
  const lines = [
    ...header('GitHub Issues 的子 issue 與「Blocked by」關係'),
    '# 工作計畫',
    '',
    '## 可以開始的工作',
    '',
    '未關閉、不是 epic、而且擋住它的 issue 都已關閉。',
    '',
  ];
  const ready = readyToStart(set);
  if (ready.length === 0) {
    lines.push('目前沒有。', '');
  } else {
    lines.push('| Issue | 標題 | Epic |', '| --- | --- | --- |');
    for (const issue of ready) {
      const epic = epicOf(issue);
      const parentCell = epic
        ? `${issueLink(epic)} ${markdownText(epic.title)}`
        : issue.parent
          ? markdownText(issue.parent)
          : '—';
      lines.push(
        `| ${issueLink(issue)} | ${markdownText(issue.title)} | ${parentCell} |`,
      );
    }
    lines.push('');
  }

  lines.push(
    '## 各 epic 的依賴圖',
    '',
    '每個 epic 一張圖，只畫未關閉的子 issue；箭頭 `a --> b` 表示 a 擋住 b（b 的「Blocked by」）。粗框是可以開始的工作，虛線框是其他 epic 裡擋住它的 issue；點節點開啟 issue。',
    '',
  );
  const children = new Map<string, Issue[]>();
  for (const issue of set.issues) {
    const epic = epicOf(issue);
    if (!epic) continue;
    children.set(epic.key, [...(children.get(epic.key) ?? []), issue]);
  }
  const epics = set.issues.filter((issue) => issue.epic);
  const shown = epics.filter(
    (epic) =>
      epic.open || (children.get(epic.key) ?? []).some((issue) => issue.open),
  );
  for (const epic of shown)
    lines.push(...epicSection(epic, children.get(epic.key) ?? []));
  const hidden = epics.length - shown.length;
  if (shown.length === 0) lines.push('目前沒有未完成的 epic。', '');
  if (hidden > 0) lines.push(`另有 ${hidden} 個已完成的 epic（未列出）。`, '');

  lines.push('## 不屬於任何 epic 的 issue', '');
  const loose = set.issues.filter(
    (issue) => issue.open && !issue.epic && !epicOf(issue),
  );
  if (loose.length === 0) {
    lines.push('目前沒有。', '');
  } else {
    lines.push('| Issue | 標題 | 狀態 |', '| --- | --- | --- |');
    for (const issue of loose) {
      lines.push(
        `| ${issueLink(issue)} | ${markdownText(issue.title)} | ${openBlockers(issue)} |`,
      );
    }
    lines.push('');
  }
  return lines.join('\n');
}

/** One section per architecture level, in the graph's (config) order. */
export function renderArchitecture(
  graph: ArchitectureGraph,
  repository: string,
): string {
  const docs = `https://github.com/${repository}/tree/HEAD/docs/architecture`;
  const lines = [
    ...header('`tools/architecture-graph.ts` 產生的架構圖 JSON'),
    '# 架構總覽',
    '',
    `與 repo 裡的 [docs/architecture](${docs}) 同一份圖；箭頭 \`a --> b\` 表示 a 依賴 b。各層的說明與規則見該目錄。`,
    '',
  ];
  for (const [id, level] of Object.entries(graph.levels)) {
    lines.push(
      `## ${markdownText(level.label ?? id)}`,
      '',
      '```mermaid',
      renderMermaid(level),
      '```',
      '',
    );
  }
  return lines.join('\n');
}

function renderHome(
  repository: string,
  commit: string,
  generatedAt: string,
): string {
  return [
    ...header('GitHub Issues 與 `tools/architecture-graph.ts`'),
    `# ${markdownText(repository)} 總覽`,
    '',
    '| 頁面 | 內容 |',
    '| --- | --- |',
    `| [[${PAGE_NAMES.workPlan}]] | 可以開始的工作、各 epic 的子 issue 依賴圖、不屬於 epic 的 issue |`,
    `| [[${PAGE_NAMES.architecture}]] | Nx 專案、runtime 上下文與 UI 模組的依賴圖 |`,
    '',
    `${GENERATED_AT_PREFIX}${generatedAt}・來源 commit：[\`${commit.slice(0, 7)}\`](https://github.com/${repository}/commit/${commit})`,
    '',
  ].join('\n');
}

interface Page {
  name: string;
  content: string;
}

/** All pages, in {@link PAGE_NAMES} order. */
export function renderPages(input: {
  issues: IssueSet;
  graph: ArchitectureGraph;
  commit: string;
  generatedAt: string;
}): Page[] {
  return [
    {
      name: PAGE_NAMES.home,
      content: renderHome(
        input.issues.repository,
        input.commit,
        input.generatedAt,
      ),
    },
    { name: PAGE_NAMES.workPlan, content: renderWorkPlan(input.issues) },
    {
      name: PAGE_NAMES.architecture,
      content: renderArchitecture(input.graph, input.issues.repository),
    },
  ];
}

/** Page content without its generated-time line, and with LF line ends. */
function comparable(content: string): string {
  return content
    .replaceAll('\r\n', '\n')
    .split('\n')
    .filter((line) => !line.startsWith(GENERATED_AT_PREFIX))
    .join('\n');
}

// ---- CLI ------------------------------------------------------------------------

interface CliIo {
  readFile: (path: string) => string;
  /** The page file `<directory>/<name>.md`, or undefined when missing. */
  readPage: (directory: string, name: string) => string | undefined;
  writePage: (directory: string, name: string, content: string) => void;
  /** The generated time, an ISO 8601 string. */
  now: () => string;
  stdout: (text: string) => void;
  stderr: (text: string) => void;
}

const VALUE_FLAGS = ['--issues', '--graph', '--out', '--commit'] as const;

const USAGE =
  'Usage: node tools/wiki-overview.ts --print-query\n' +
  '       node tools/wiki-overview.ts --issues <issues.json> --graph <graph.json> --out <wiki-dir> --commit <sha>\n' +
  '  --print-query  print the GraphQL query for `gh api graphql --paginate --slurp`\n' +
  '  --issues       its output (variables owner and name)\n' +
  '  --graph        the JSON printed by tools/architecture-graph.ts\n' +
  '  --out          the wiki checkout; pages are written only when more than\n' +
  '                 their generated-time line changed\n' +
  '  --commit       the source commit shown on Home\n';

function withoutBom(value: string): string {
  return value.replace(/^\uFEFF/u, '');
}

function parseGraph(path: string, value: string): ArchitectureGraph {
  const graph = JSON.parse(withoutBom(value)) as Partial<ArchitectureGraph>;
  if (graph.schemaVersion !== 1 || !graph.levels) {
    throw new Error(`${path} is not an architecture graph (schemaVersion 1).`);
  }
  return graph as ArchitectureGraph;
}

/** Returns the process exit code: 0 ok, 2 bad usage. */
export function runCli(argv: string[], io: CliIo): number {
  if (argv.length === 1 && argv[0] === '--print-query') {
    io.stdout(ISSUES_QUERY);
    return 0;
  }
  const options = new Map<string, string>();
  for (let index = 0; index < argv.length; index += 2) {
    const [flag, value] = [argv[index], argv[index + 1]];
    if (
      !(VALUE_FLAGS as readonly string[]).includes(flag) ||
      !value ||
      options.has(flag)
    ) {
      io.stderr(USAGE);
      return 2;
    }
    options.set(flag, value);
  }
  if (options.size !== VALUE_FLAGS.length) {
    io.stderr(USAGE);
    return 2;
  }
  const option = (flag: (typeof VALUE_FLAGS)[number]): string =>
    options.get(flag) as string;
  const issuesPath = option('--issues');
  const graphPath = option('--graph');
  const out = option('--out');
  const pages = renderPages({
    issues: parseIssues(JSON.parse(withoutBom(io.readFile(issuesPath)))),
    graph: parseGraph(graphPath, io.readFile(graphPath)),
    commit: option('--commit'),
    generatedAt: io.now(),
  });
  const changed = pages.filter((page) => {
    const existing = io.readPage(out, page.name);
    return (
      existing === undefined ||
      comparable(existing) !== comparable(page.content)
    );
  });
  if (changed.length === 0) {
    io.stdout('The wiki pages are up to date.\n');
    return 0;
  }
  for (const page of pages) io.writePage(out, page.name, page.content);
  io.stdout(
    `Wrote ${pages.length} wiki pages; changed: ${changed.map((page) => page.name).join(', ')}.\n`,
  );
  return 0;
}

// ---- Process boundary -----------------------------------------------------------

if (
  process.argv[1] &&
  resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  const pagePath = (directory: string, name: string): string =>
    join(directory, `${name}.md`);
  try {
    process.exitCode = runCli(process.argv.slice(2), {
      readFile: (path) => readFileSync(path, 'utf8'),
      readPage: (directory, name) =>
        existsSync(pagePath(directory, name))
          ? readFileSync(pagePath(directory, name), 'utf8')
          : undefined,
      writePage: (directory, name, content) => {
        mkdirSync(directory, { recursive: true });
        writeFileSync(pagePath(directory, name), content, 'utf8');
      },
      now: () => new Date().toISOString(),
      stdout: (output) => process.stdout.write(output),
      stderr: (output) => process.stderr.write(output),
    });
  } catch (error) {
    process.stderr.write(`wiki-overview: ${(error as Error).message}\n`);
    process.exitCode = 1;
  }
}
